def comps(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b))
                    if g[a][b]!=col: continue
                    cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and g[x][y]==col and (x,y) not in seen:
                                st.append((x,y))
                out.append((col,len(cells),min(a for a,b in cells),min(b for a,b in cells),sorted(cells)))
    return out
